import sys
import math
(n, m) = input().strip().split(' ')
(n, m) = [int(n), int(m)]
dim = math.ceil(math.log(n) / math.log(m))
if n < 4:
	dim = 1
if n < 6:
	dim = 2
print(dim)
if n == 5:
	print('1 4\n2 0\n3 1\n4 2\n0 3')
else:
	for i in range(n):
		print(' '.join([str((i * m + c) % n) for c in range(m)]))
